import { createReadStream } from 'node:fs';
import { copyFile, mkdir, readFile, rm } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { Readable } from 'node:stream';
import { AwsClient } from 'aws4fetch';
import type { AppConfig } from '../core/config.js';

/**
 * Where file contents live (P-OPS-06). Keys are generated by Tasklore (e.g. attachments/<uuid>),
 * never taken from user input.
 */
export interface FileStore {
  readonly kind: 'local' | 's3';
  /** Prepares the store (directory, bucket); safe to call on every start. */
  init(): Promise<void>;
  /** Stores the contents of a local file under the key. */
  put(key: string, sourcePath: string, contentType: string): Promise<void>;
  get(key: string): Promise<Readable>;
  /** Removes an object; a missing object is not an error. */
  delete(key: string): Promise<void>;
}

const KEY = /^[a-z0-9-]+(\/[a-z0-9-]+)*$/;

function checkKey(key: string): string {
  if (!KEY.test(key)) throw new Error(`Invalid storage key "${key}"`);
  return key;
}

export class FileNotFoundError extends Error {
  constructor(key: string) {
    super(`No stored file for "${key}"`);
  }
}

/** Files in a directory on the local disk (or a mounted volume). */
export class LocalFileStore implements FileStore {
  readonly kind = 'local';
  private readonly root: string;

  constructor(directory: string) {
    this.root = resolve(directory);
  }

  private path(key: string): string {
    return resolve(this.root, checkKey(key));
  }

  async init(): Promise<void> {
    await mkdir(this.root, { recursive: true });
  }

  async put(key: string, sourcePath: string): Promise<void> {
    const target = this.path(key);
    await mkdir(dirname(target), { recursive: true });
    await copyFile(sourcePath, target);
  }

  async get(key: string): Promise<Readable> {
    const stream = createReadStream(this.path(key));
    // Surface a missing file as a typed error before the response starts.
    await new Promise<void>((resolveOpen, reject) => {
      stream.once('open', () => resolveOpen());
      stream.once('error', (error: NodeJS.ErrnoException) =>
        reject(error.code === 'ENOENT' ? new FileNotFoundError(key) : error),
      );
    });
    return stream;
  }

  async delete(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }
}

export interface S3Options {
  endpoint: string;
  region: string;
  bucket: string;
  accessKeyId: string;
  secretAccessKey: string;
}

/**
 * S3-compatible object storage (RustFS, AWS S3, …) with path-style addressing, signed with
 * SigV4 by aws4fetch (E-43). Only the four object operations Tasklore needs.
 */
export class S3FileStore implements FileStore {
  readonly kind = 's3';
  private readonly client: AwsClient;
  private readonly base: string;

  constructor(private readonly options: S3Options) {
    this.client = new AwsClient({
      accessKeyId: options.accessKeyId,
      secretAccessKey: options.secretAccessKey,
      region: options.region,
      service: 's3',
    });
    this.base = `${options.endpoint.replace(/\/+$/, '')}/${encodeURIComponent(options.bucket)}`;
  }

  private url(key: string): string {
    return `${this.base}/${checkKey(key)}`;
  }

  private async fail(response: Response, action: string): Promise<never> {
    const body = await response.text().catch(() => '');
    throw new Error(`S3 ${action} failed with ${response.status}: ${body.slice(0, 300)}`);
  }

  /** Creates the bucket when it does not exist yet. */
  async init(): Promise<void> {
    const head = await this.client.fetch(this.base, { method: 'HEAD' });
    if (head.ok) return;
    if (head.status !== 404) await this.fail(head, `checking bucket ${this.options.bucket}`);
    const created = await this.client.fetch(this.base, { method: 'PUT' });
    if (!created.ok && created.status !== 409) {
      await this.fail(created, `creating bucket ${this.options.bucket}`);
    }
  }

  async put(key: string, sourcePath: string, contentType: string): Promise<void> {
    // Attachments are size-limited, so one signed PUT of the whole body is enough.
    const body = await readFile(sourcePath);
    const response = await this.client.fetch(this.url(key), {
      method: 'PUT',
      body,
      headers: { 'content-type': contentType },
    });
    if (!response.ok) await this.fail(response, `storing ${key}`);
  }

  async get(key: string): Promise<Readable> {
    const response = await this.client.fetch(this.url(key));
    if (response.status === 404) throw new FileNotFoundError(key);
    if (!response.ok || !response.body) return this.fail(response, `reading ${key}`);
    return Readable.fromWeb(response.body as import('node:stream/web').ReadableStream);
  }

  async delete(key: string): Promise<void> {
    const response = await this.client.fetch(this.url(key), { method: 'DELETE' });
    if (!response.ok && response.status !== 404) await this.fail(response, `deleting ${key}`);
  }
}

export function createFileStore(config: AppConfig): FileStore {
  if (config.STORAGE_DRIVER === 's3') {
    return new S3FileStore({
      endpoint: config.S3_ENDPOINT as string,
      region: config.S3_REGION,
      bucket: config.S3_BUCKET as string,
      accessKeyId: config.S3_ACCESS_KEY_ID as string,
      secretAccessKey: config.S3_SECRET_ACCESS_KEY as string,
    });
  }
  return new LocalFileStore(config.STORAGE_LOCAL_DIR);
}
